// Surface textures generated by tools/generate-textures.py, in texture-array layer order.
// scale = world units per repeat (a map tile is 1 unit).
// bump = relief strength for the normal map derived from the texture's brightness: dark joints and
// cracks become grooves. Negative inverts it, for brick where the mortar is the light part.
export const TEXTURES = [
  ['asphalt', 6, 0.25], ['sidewalk', 4.5, 1.0], ['plaza', 3, 1.2], ['floor', 3, 0.8], ['grass', 4, 0.6], ['dirt', 4, 0.5], ['roof', 5, 0.5],
  // wall-only layers (brick..posters): flat tops fall back to concrete in the shader
  ['brick', 2.5, -1.2], ['concrete', 3, 0.7], ['stucco', 3, 0.5], ['metal', 2, 1.0], ['graffiti', 3, 0.3], ['posters', 2.5, 0.3],
  ['scorch', 1, 0], ['blood', 1, 0],
];
export const T = Object.fromEntries(TEXTURES.map(([id], k) => [id, k]));

// An instance's material id can carry a texture layer: mat | (layer + 1) << 4.
export const tex = (mat, id) => mat | ((T[id] + 1) << 4);
